{
  "claims": [
    {"text": "The crew was able to reprogram the FMC and complete the approach to the newly assigned runway.", "anchor": "R2.S2"},
    {"text": "The crew flew through the localizer during a late runway change.", "anchor": "R3.S1"}
  ],
  "key_hazards": [
    {"text": "Late runway change during approach", "anchor": "R1.S1"},
    {"text": "Unstable approach", "anchor": "R4.S1"},
    {"text": "Missed approach", "anchor": "R5.S1"}
  ],
  "recommended_phraseology": [
    "REQUEST CHANGE TO (frequency)",
    "FREQUENCY CHANGE APPROVED",
    "CLEARED APPROACH [RUNWAY (number)]"
  ]
}

{
  "claims": [
    {"text": "The final controller reported a loss of separation on final due to strong winds.", "anchor": "R1.S2"},
    {"text": "The pilot continued to land after the approach to the new runway became unstabilized.", "anchor": "R2.S2"}
  ],
  "key_hazards": [
    {"text": "Loss of separation on final", "anchor": "R1.S2"},
    {"text": "Unstable approach", "anchor": "R2.S2"},
    {"text": "Aircraft on final to a closed runway", "anchor": "R3.S1"}
  ],
  "recommended_phraseology": [
    "REPORT BASE",
    "REPORT ESTABLISHED ON LOCALIZER",
    "ON TRACK"
  ]
}

{
  "claims": [
    {"text": "ATC assigned a different landing runway during arrival.", "anchor": "R1.S1"},
    {"text": "The aircraft was assigned the wrong runway.", "anchor": "R2.S2"}
  ],
  "key_hazards": [
    {"text": "Track deviation occurred.", "anchor": "R1.S1"},
    {"text": "Route discontinuities generated.", "anchor": "R1.S1"},
    {"text": "Another aircraft on final approach took evasive action.", "anchor": "R2.S3"}
  ],
  "recommended_phraseology": [
    "CLEARED (or PROCEED) (designation) ARRIVAL",
    "NO [ATC] SPEED RESTRICTIONS"
  ]
}

{
  "claims": [
    {"text": "The new runway was assigned close to touchdown.", "anchor": "R1.S1"},
    {"text": "There was no alert regarding the new parallel runway.", "anchor": "R2.S1"}
  ],
  "key_hazards": [
    {"text": "Potential confusion for pilots to land on the wrong runway.", "anchor": "R2.S2"},
    {"text": "Vehicle on runway.", "anchor": "R4.S1"},
    {"text": "Wake turbulence.", "anchor": "R3.S1"}
  ],
  "recommended_phraseology": [
    "FROM TOUCHDOWN",
    "FROM TOUCHDOWN. ALTITUDE (or HEIGHT) SHOULD BE (numbers and units)"
  ]
}

{
  "claims": [
    {"text": "A late runway change during approach can result in a momentary track deviation.", "anchor": "R2.S1"},
    {"text": "A late runway change requiring FMS reprogramming can cause a track deviation.", "anchor": "R3.S1"}
  ],
  "key_hazards": [
    {"text": "Late runway change", "anchor": "R1.S1"},
    {"text": "FMS reprogramming issue", "anchor": "R4.S2"},
    {"text": "FMS design issue", "anchor": "R4.S2"}
  ],
  "recommended_phraseology": [
    "REQUEST CHANGE TO (frequency)",
    "FREQUENCY CHANGE APPROVED",
    "CLEARED APPROACH [RUNWAY (number)]"
  ]
}

{
  "claims": [
    {"text": "A B737 crew accepted a last minute change for a runway 19L night visual.", "anchor": "R1.S1"},
    {"text": "A CRJ200 crew experienced an unstabilized approach with stick shaker activation due to spoilers being fully extended and forgotten.", "anchor": "R2.S1"}
  ],
  "key_hazards": [
    {"text": "Last minute runway change", "anchor": "R1.S1"},
    {"text": "Unstabilized approach", "anchor": "R2.S1"},
    {"text": "Altitude deviation", "anchor": "R3.S2"}
  ],
  "recommended_phraseology": [
    "REQUEST VISUAL APPROACH",
    "CLEARED VISUAL APPROACH RUNWAY",
    "REPORT VISUAL"
  ]
}

{
  "claims": [
    {"text": "The crew went around after a premature runway change.", "anchor": "R1.S1"},
    {"text": "A go-around was initiated due to a TCAS RA involving traffic on a parallel runway.", "anchor": "R2.S1"}
  ],
  "key_hazards": [
    {"text": "Unstable approach", "anchor": "R3.S1"},
    {"text": "Potential conflict", "anchor": "R4.S1"},
    {"text": "Runway incursion", "anchor": "R5.S1"}
  ],
  "recommended_phraseology": [
    "GO AROUND",
    "IN CASE OF GO AROUND (instructions)",
    "GO AROUND IMMEDIATELY [missed approach instructions]"
  ]
}

{
  "claims": [
    {"text": "The crew encountered a false localizer intercept when cleared for the ILS runway.", "anchor": "R1.S1"},
    {"text": "The crew misinterpreted a visual approach clearance appended to a cleared heading.", "anchor": "R2.S1"}
  ],
  "key_hazards": [
    {"text": "False localizer intercept", "anchor": "R1.S1"},
    {"text": "Misinterpretation of ATC clearance", "anchor": "R2.S1"},
    {"text": "Inadequate autopilot tuning", "anchor": "R5.S2"}
  ],
  "recommended_phraseology": [
    "RUNWAY (number) CLEARED TO LAND",
    "RUNWAY (number) CLEARED FOR TAKE-OFF [REPORT AIRBORNE]",
    "CLEARED APPROACH [RUNWAY (number)]"
  ]
}

{
  "claims": [
    {"text": "The controller switched the landing runway due to traffic.", "anchor": "R1.S1"},
    {"text": "The landing aircraft was switched to ground control.", "anchor": "R1.S2"}
  ],
  "key_hazards": [
    {"text": "Runway incursion", "anchor": "R5.S1"},
    {"text": "Less than clear ADW procedures", "anchor": "R2.S1"},
    {"text": "Reduced visibility", "anchor": "R5.S2"}
  ],
  "recommended_phraseology": [
    "DUE TRAFFIC",
    "TRAFFIC (information)",
    "(traffic information) RUNWAY (number) CLEARED TO LAND"
  ]
}

{
  "claims": [
    {"text": "Runway reassignment caused confusion on approach.", "anchor": "R1.S1"},
    {"text": "Runway changes led to confusion and an altitude deviation.", "anchor": "R2.S2"}
  ],
  "key_hazards": [
    {"text": "Confusion on approach", "anchor": "R1.S1"},
    {"text": "Altitude deviation", "anchor": "R2.S3"},
    {"text": "Displaced threshold not depicted on airport diagram", "anchor": "R3.S3"}
  ],
  "recommended_phraseology": [
    "CLEARED APPROACH [RUNWAY (number)]",
    "ON TRACK",
    "REPORT ESTABLISHED ON LOCALIZER (or ON [GLS/RNP/MLS] [FINAL] APPROACH [COURSE])"
  ]
}

{
  "claims": [
    {"text": "The aircraft pitched up unexpectedly while established on the localizer.", "anchor": "R1.S1"},
    {"text": "The crew elected to continue landing due to a potential conflict with a departing aircraft.", "anchor": "R4.S2"}
  ],
  "key_hazards": [
    {"text": "Late runway change", "anchor": "R4.S1"},
    {"text": "Unstable approach", "anchor": "R4.S2"},
    {"text": "UAV encounter", "anchor": "R5.S1"}
  ],
  "recommended_phraseology": [
    "REPORT ESTABLISHED ON LOCALIZER",
    "REPORT ESTABLISHED ON GLIDE PATH"
  ]
}

{
  "claims": [
    {"text": "Traffic being vectored for a parallel runway crossed the final approach course.", "anchor": "R1.S1"},
    {"text": "The tower waited to change the runway of an arrival that was catching the preceding arrival.", "anchor": "R5.S1"}
  ],
  "key_hazards": [
    {"text": "Traffic conflicted with parallel runway traffic.", "anchor": "R1.S1"},
    {"text": "Traffic failed to follow the thirty degree intercept instruction.", "anchor": "R4.S1"},
    {"text": "The pilot lined up for a parallel runway due to fatigue and distraction.", "anchor": "R3.S1"}
  ],
  "recommended_phraseology": [
    "REQUEST LEVEL (or FLIGHT LEVEL or ALTITUDE) CHANGE FROM (name of unit) [AT (time or significant point)]",
    "REQUEST CHANGE TO (frequency)",
    "CLEARED FOR (type of approach) APPROACH RUNWAY (number) LEFT (or RIGHT)"
  ]
}

{
  "claims": [
    {"text": "Multiple go-arounds occurred due to excessive tailwinds by arriving aircraft.", "anchor": "R1.S2"},
    {"text": "ATC changed the departure runway creating an unacceptable tailwind takeoff condition.", "anchor": "R3.S1"}
  ],
  "key_hazards": [
    {"text": "Wind direction changes", "anchor": "R1.S1"},
    {"text": "Tailwinds", "anchor": "R1.S2"},
    {"text": "Obstruction", "anchor": "R2.S1"}
  ],
  "recommended_phraseology": [
    "[SURFACE] WIND (number) DEGREES (speed) (units)",
    "WIND AT (level) (number) DEGREES (number) (KNOTS)",
    "DUE TRAFFIC"
  ]
}

{
  "claims": [
    {"text": "The flight crew received a new clearance enroute to avoid weather, but it resulted in a runway change while vectoring to final.", "anchor": "R1.S1"},
    {"text": "The pilot was asked to slow down on final, but couldn't because the aircraft was already at approach speed, leading to a perceived unsafe situation.", "anchor": "R2.S1"}
  ],
  "key_hazards": [
    {"text": "Runway change while vectoring to final", "anchor": "R1.S2"},
    {"text": "Late runway change", "anchor": "R2.S1"},
    {"text": "Loss of separation", "anchor": "R5.S1"}
  ],
  "recommended_phraseology": [
    "CLEARED TO THE FINAL APPROACH FIX",
    "REQUEST (distance) FINAL",
    "REQUEST CHANGE TO (frequency)"
  ]
}

{
  "claims": [
    {"text": "The crew experienced an FMS anomaly during approach.", "anchor": "R1.S1"},
    {"text": "The runway was changed twice during approach.", "anchor": "R1.S2"}
  ],
  "key_hazards": [
    {"text": "Runway change during approach.", "anchor": "R1.S2"},
    {"text": "FMS anomaly during approach.", "anchor": "R1.S1"},
    {"text": "Track deviation during approach.", "anchor": "R4.S3"}
  ],
  "recommended_phraseology": [
    "CLEARED (or PROCEED) (designation) ARRIVAL",
    "CLEARED APPROACH [RUNWAY (number)]",
    "REQUEST (type of approach) APPROACH [RUNWAY (number)]"
  ]
}

{
  "claims": [
    {"text": "A taxiing aircraft crossed the landing runway with traffic on short final.", "anchor": "R1.S1"},
    {"text": "The pilot elected to turn right after a go-around on short final.", "anchor": "R2.S1"}
  ],
  "key_hazards": [
    {"text": "Runway incursion", "anchor": "R1.S1"},
    {"text": "Traffic on short final", "anchor": "R3.S2"},
    {"text": "Taxiing aircraft entering the runway", "anchor": "R4.S1"}
  ],
  "recommended_phraseology": [
    "EXPEDITE CROSSING RUNWAY (number) TRAFFIC (aircraft type) (distance) (MILES) FINAL",
    "(traffic information) RUNWAY (number) CLEARED TO LAND",
    "(traffic information) RUNWAY (number) CLEARED FOR TAKE-OFF"
  ]
}

{
  "claims": [
    {"text": "The pilot continued to land after the approach became unstabilized.", "anchor": "R1.S2"},
    {"text": "The crew was able to complete the approach to the newly assigned runway.", "anchor": "R2.S2"}
  ],
  "key_hazards": [
    {"text": "Late runway change", "anchor": "R2.S1"},
    {"text": "Unstabilized approach", "anchor": "R1.S2"},
    {"text": "Mistakenly lined up for the wrong runway", "anchor": "R5.S3"}
  ],
  "recommended_phraseology": [
    "THIS WILL BE A PRECISION RADAR APPROACH RUNWAY (number)",
    "APPROACH COMPLETED [CONTACT (unit)]"
  ]
}

{
  "claims": [
    {"text": "The crew commenced a go-around above 4,000 ft but insufficient thrust was added.", "anchor": "R1.S2"},
    {"text": "A pilot was assigned a visual approach to the wrong runway.", "anchor": "R3.S2"}
  ],
  "key_hazards": [
    {"text": "Late runway change", "anchor": "R1.S1"},
    {"text": "Insufficient thrust", "anchor": "R1.S2"},
    {"text": "Incorrect runway alignment", "anchor": "R3.S2"}
  ],
  "recommended_phraseology": [
    "REQUEST CHANGE TO (frequency)",
    "TAXI TO HOLDING POINT [number] [RUNWAY (number) VIA (specific route), [HOLD SHORT OF RUNWAY (number) or [CROSS RUNWAY (number)]",
    "CROSS RUNWAY (number) [REPORT VACATED]"
  ]
}

{
  "claims": [
    {"text": "ATC issued a circle-to-land to a different runway late in approach.", "anchor": "R1.S1"},
    {"text": "ATC issued a go-around during final approach when previous landing traffic did not clear the runway.", "anchor": "R4.S1"}
  ],
  "key_hazards": [
    {"text": "Unstabilized approach", "anchor": "R1.S2"},
    {"text": "Late landing gear retraction", "anchor": "R1.S2"},
    {"text": "Altitude overshoot", "anchor": "R1.S2"}
  ],
  "recommended_phraseology": [
    "RUNWAY (number) CLEARED TO LAND",
    "(traffic information) RUNWAY (number) CLEARED TO LAND",
    "MAKE STRAIGHT-IN (or CIRCLING APPROACH, LEFT (or RIGHT) TURN TO (location)) CLEARED TO LAND"
  ]
}
